// ─── PARSER anti-crise.fr ──────────────────────────────────────────────────
// Source : WordPress REST API anti-crise.fr
// Chaque item = un article de blog avec titre (enseigne) + contenu HTML (produits)

const FOOD_KEYWORDS = [
  'lait','yaourt','fromage','beurre','crème fraîche','oeuf','oeufs','feta','mozzarella',
  'camembert','emmental','comté','chèvre','ricotta','mascarpone',
  'poulet','boeuf','porc','veau','agneau','saumon','thon','crevette','cabillaud',
  'jambon','lardons','bacon','saucisse','merguez','chipolata','canard','steak',
  'tomate','carotte','courgette','oignon','salade','poireau','brocoli','poivron',
  'avocat','concombre','champignon','épinard','aubergine','haricot vert',
  'pomme','banane','orange','poire','fraise','raisin','melon','pêche','citron','ananas',
  'pâtes','riz','farine','pain','baguette','céréales','lentilles','quinoa','semoule',
  'huile','sauce tomate','moutarde','mayonnaise','ketchup','vinaigre','sel','sucre',
  'eau','jus de','café','thé','bière','vin','sirop','limonade','lait végétal',
  'pizza','surgelé','conserve','maïs','soupe','bouillon','confiture','miel',
];

const CATEGORY_MAP = [
  [['fruit','légume','pomme de terre','carotte','poivron','salade','courgette','tomate','concombre','épinard','brocoli','oignon','ail','poireau','aubergine','champignon','avocat','banane','poire','pêche','fraise','cerise','raisin','melon','ananas','orange','citron'], 'Fruits & Légumes'],
  [['viande','boucherie','poulet','boeuf','porc','veau','agneau','côte','steak','filet','canard','lapin','dinde','rôti'], 'Viandes & Poissons'],
  [['poisson','saumon','thon','crevette','cabillaud','moule','huître','calamar','dorade','bar','truite','sardine'], 'Viandes & Poissons'],
  [['lait','yaourt','fromage','beurre','crème','laitier','oeuf','feta','emmental','camembert','chèvre','mozzarella'], 'Produits Laitiers'],
  [['surgelé','congel','ice cream','glace'], 'Surgelés'],
  [['pain','boulang','viennoiserie','brioche','baguette','croissant','madeleine'], 'Boulangerie'],
  [['bière','vin','eau','jus','boisson','soda','café','thé','sirop','cidre','champagne'], 'Boissons'],
  [['jambon','charcuterie','saucisson','lardons','bacon','rillette','pâté','chorizo'], 'Charcuterie'],
];

const STORE_NAMES = [
  'auchan','carrefour','leclerc','lidl','intermarché','super u','simply market',
  'monoprix','franprix','netto','leader price','aldi','casino','cora','match',
  'biocoop','naturalia','picard','les mousquetaires',
];

function guessCategory(text) {
  const lower = text.toLowerCase();
  for (const [keywords, cat] of CATEGORY_MAP) {
    if (keywords.some(k => lower.includes(k))) return cat;
  }
  return 'Épicerie';
}

function isFood(text) {
  const lower = text.toLowerCase();
  return FOOD_KEYWORDS.some(k => lower.includes(k)) ||
    CATEGORY_MAP.some(([kws]) => kws.some(k => lower.includes(k)));
}

function extractStoreName(title) {
  const lower = title.toLowerCase();
  for (const store of STORE_NAMES) {
    if (lower.includes(store)) {
      return store.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
    }
  }
  // Fallback : premier mot capitalisé du titre
  const match = title.match(/Catalogue\s+(\w+)/i) || title.match(/Prospectus\s+(\w+)/i);
  return match ? match[1] : title.split(' ')[0];
}

function stripHtml(html) {
  return html
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ').replace(/&#\d+;/g, '')
    .replace(/[ \t]+/g, ' ')
    .trim();
}

function parseDate(str) {
  if (!str) return null;
  try { return new Date(str).toISOString().split('T')[0]; } catch { return null; }
}

function nextSunday() {
  const d = new Date();
  d.setDate(d.getDate() + (7 - d.getDay() || 7));
  return d.toISOString().split('T')[0];
}

const deals = [];
const posts = $input.all();

for (const input of posts) {
  const raw = input.json;
  // L'API renvoie un tableau ou un objet unique
  const list = Array.isArray(raw) ? raw : [raw];

  for (const post of list) {
    const title = post.title?.rendered || post.title || '';
    const html = post.content?.rendered || post.content || '';
    const postDate = post.date || null;

    if (!html) continue;

    const storeName = extractStoreName(title);
    const text = stripHtml(html);
    const lines = text.split('\n').map(l => l.trim()).filter(l => l.length > 2);

    // Cherche les patterns : "Nom produit ... X,XX€" ou "X,XX € ... Nom"
    // Prix au format 1,99 / 12.50 / 0,89
    const priceRegex = /(\d{1,3}[,.]\d{2})\s*€?/g;

    for (const line of lines) {
      const priceMatches = [...line.matchAll(/(\d{1,3}[,.]\d{2})\s*€/g)];
      if (priceMatches.length === 0) continue;

      // Extraire le nom : texte avant le premier prix
      const firstPriceIdx = line.indexOf(priceMatches[0][0]);
      let name = line.substring(0, firstPriceIdx).replace(/[-–—:|]/g, ' ').trim();

      // Nettoyer le nom
      name = name
        .replace(/\d+\s*(g|kg|ml|cl|l|litres?|pièces?|unités?|x\d+)/gi, '')
        .replace(/\s+/g, ' ')
        .trim();

      if (name.length < 3 || name.length > 80) continue;
      if (!isFood(name + ' ' + line)) continue;

      const pricePromo = parseFloat(priceMatches[0][1].replace(',', '.'));
      const priceNormal = priceMatches.length > 1
        ? parseFloat(priceMatches[1][1].replace(',', '.'))
        : null;

      if (isNaN(pricePromo) || pricePromo <= 0 || pricePromo > 200) continue;

      // Extraire l'unité si mentionnée dans la ligne (ex: "le kg", "la pièce", "500g")
      const unitMatch = line.match(/(le\s+kg|la\s+pièce|\d+\s*g\b|\d+\s*kg\b|\d+\s*cl\b|\d+\s*l\b|\d+\s*ml\b)/i);

      deals.push({
        item: name.charAt(0).toUpperCase() + name.slice(1).toLowerCase(),
        chain: storeName,
        brand: null,
        price_promo: Math.round(pricePromo * 100) / 100,
        price_normal: priceNormal && priceNormal > pricePromo ? Math.round(priceNormal * 100) / 100 : null,
        unit: unitMatch ? unitMatch[0].trim() : null,
        valid_until: nextSunday(),
        region: 'national',
        category: guessCategory(name + ' ' + line),
      });
    }
  }
}

// Dédoublonner : meilleur prix par article+enseigne
const seen = new Map();
const deduped = [];
for (const d of deals) {
  const key = `${d.item.toLowerCase().slice(0, 20)}-${d.chain.toLowerCase()}`;
  const ex = seen.get(key);
  if (!ex || d.price_promo < ex.price_promo) {
    seen.set(key, d);
    deduped.push(d);
    if (ex) deduped.splice(deduped.indexOf(ex), 1);
  }
}

return [{ json: { deals: deduped, count: deduped.length, source: 'anti-crise.fr' } }];
